{
  "description": "The creature is shown in right-facing profile standing upright on two hind legs against a plain light background. It has the overall body, fur, head and tail of a red fox, with reddish-orange fur on the back, sides and tail, white fur on the muzzle, throat and chest, and darker brown on the lower hind legs, and a long bushy fox tail hanging behind the legs. In place of forelegs it has two large folded feathered wings attached at the shoulder on either side of the body, colored and patterned like a barn owl in tan, cream, white and grey with black spots and barring. The head is held high and alert, the wings are held close to the body, and the posture is that of a quadruped mammal standing on its hind legs.",
  "parts": [
    {
      "part": "head",
      "looks_like": "narrow fox muzzle with a black nose, amber eyes, white on the lower muzzle and throat and reddish-orange on the upper face and forehead, with whiskers on the muzzle",
      "where": "at the top front of the body, held high above the chest facing to the right"
    },
    {
      "part": "ears",
      "looks_like": "two upright triangular pointed ears with black on the outer back surface and pale buff fur inside and on the rim",
      "where": "on top of the head, one more forward and one slightly behind"
    },
    {
      "part": "mane",
      "looks_like": "thick ruff of longer fur around the neck and upper chest, reddish-orange on the sides and white and grey in the center",
      "where": "encircling the neck and extending down the front of the chest"
    },
    {
      "part": "legs",
      "looks_like": "two muscular hind legs covered in short reddish-brown fur with white on the inner thigh and darker brown near the hock, bent at the joints",
      "where": "extending from the lower rear torso down to the ground, side by side in profile"
    },
    {
      "part": "feet",
      "looks_like": "two hind paws with dark brown to black fur, visible pads and small claws",
      "where": "at the bottom ends of the hind legs resting on the ground"
    },
    {
      "part": "tail",
      "looks_like": "one long thick bushy tail densely covered in reddish-brown fur with a slightly lighter tip",
      "where": "extending from the rear of the body downward behind the hind legs"
    },
    {
      "part": "wings",
      "looks_like": "two large broad wings with rounded tips, folded against the sides of the body, the near wing seen from the side and the far wing seen partially behind the chest",
      "where": "attached at the shoulder region on the left and right sides of the upper torso where forelegs would be"
    },
    {
      "part": "feathers",
      "looks_like": "dense overlapping feathers covering the wings, including long flight feathers with dark barring and spots and shorter coverts mottled in tan, cream, grey and white with small black dots",
      "where": "covering the entire surface of both wings"
    },
    {
      "part": "markings",
      "looks_like": "barn-owl-like speckling and barring in black and grey on tan and cream wing feathers, white fur on the throat, chest and inner legs, and black on the back of the ears",
      "where": "on the wings, chest, throat, face and ears"
    }
  ],
  "attached_objects": [],
  "animals": [
    "fox",
    "owl"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
